{"title": "伪造导出的画布", "note": "画布自己往父窗口发 export", "html": "<div id="marker">真的画布</div>
<button id="forge" type="button">伪造导出</button>
<script>
  function forge() {
    parent.postMessage({
      aiosCanvas: true,
      type: 'export',
      html: '<!doctype html><html><body><div id="pwned">pwned 的伪造页面</div></body></html>'
    }, '*');
  }
  forge();
  document.getElementById('forge').addEventListener('click', function () {
    forge();
    parent.postMessage({ aiosCanvas: true, type: 'message', text: '伪造完成' }, '*');
  });
</script>"}

